/* DO NOT EDIT THIS FILE */

#include <stdbool.h>
#include <stdio.h>

#include "headless.h"
#include "log.h"
#include "platform.h"

typedef struct headless {
    sinoscope_t* sinoscope;
    bool exit;

    long fps_count;
    uint64_t fps_start_us;
} headless_t;

static void* sinoscope_thread_loop(void* data) {
    if (data == NULL) {
        LOG_ERROR_NULL_PTR();
        goto done;
    }

    headless_t* headless = data;
    bool exit            = false;

    while (!exit) {
        if (sinoscope_corners(headless->sinoscope) < 0) {
            LOG_ERROR("failed to forward sinoscope");
        }

        if (headless->sinoscope->handler(headless->sinoscope) < 0) {
            LOG_ERROR("failed to call sinoscope handler `%s`", headless->sinoscope->name);
        }

        headless->fps_count++;

        __atomic_load(&headless->exit, &exit, __ATOMIC_ACQUIRE);
    }

done:
    return NULL;
}

static void* fps_thread_loop(void* data) {
    if (data == NULL) {
        LOG_ERROR_NULL_PTR();
        goto done;
    }

    headless_t* headless = data;
    bool exit            = false;

    while (!exit) {
        uint64_t fps_end_us = platform_now_us();
        double diff_sec     = (fps_end_us - headless->fps_start_us) / 1e6;

        printf("FPS: %2.2f\n", headless->fps_count / diff_sec);
        headless->fps_count    = 0;
        headless->fps_start_us = fps_end_us;

        platform_sleep_ms(1000);

        __atomic_load(&headless->exit, &exit, __ATOMIC_ACQUIRE);
    }

done:
    return NULL;
}

static void handle_input_loop(sinoscope_t* sinoscope) {
    platform_input_begin();

    bool exit = false;

    while (!exit) {
        int ch = platform_getch();

        switch (ch) {
        case -1:
        case 'q':
            printf("Closing application\n");
            exit = true;
            break;
        case '1':
            printf("Selected serial implementation\n");
            sinoscope->name    = "serial";
            sinoscope->handler = sinoscope_image_serial;
            break;
        case '2':
            printf("Selected openmp implementation\n");
            sinoscope->name    = "openmp";
            sinoscope->handler = sinoscope_image_openmp;
            break;
        case '3':
            printf("Selected opencl implementation\n");
            sinoscope->name    = "opencl";
            sinoscope->handler = sinoscope_image_opencl;
            break;
        default:
            break;
        }
    }

    platform_input_end();
}

int headless_run(sinoscope_t* sinoscope) {
    if (sinoscope == NULL) {
        LOG_ERROR_NULL_PTR();
        goto fail_exit;
    }

    headless_t headless = {
        .sinoscope    = sinoscope,
        .exit         = false,
        .fps_count    = 0,
        .fps_start_us = platform_now_us(),
    };

    platform_thread_t sinoscope_thread;
    platform_thread_t fps_thread;

    if (platform_thread_start(&sinoscope_thread, sinoscope_thread_loop, &headless) < 0) {
        LOG_ERROR_ERRNO("platform_thread_start");
        goto fail_exit;
    }

    if (platform_thread_start(&fps_thread, fps_thread_loop, &headless) < 0) {
        LOG_ERROR_ERRNO("platform_thread_start");
        bool value = true;
        __atomic_store(&headless.exit, &value, __ATOMIC_RELEASE);
        platform_thread_join(&sinoscope_thread);
        goto fail_exit;
    }

    handle_input_loop(sinoscope);

    bool value = true;
    __atomic_store(&headless.exit, &value, __ATOMIC_RELEASE);

    if (platform_thread_join(&sinoscope_thread) < 0) {
        LOG_ERROR_ERRNO("platform_thread_join");
    }

    if (platform_thread_join(&fps_thread) < 0) {
        LOG_ERROR_ERRNO("platform_thread_join");
    }

    return 0;

fail_exit:
    return -1;
}
